package com.example.agriculturalapp.data.local

import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.map

/**
 * In-Memory implementation of ResponseDao for testing purposes.
 * This implementation stores all data in memory without persistence.
 *
 * Clean Architecture: Part of the Data Layer (Local Data Source)
 * Follows: Single Responsibility Principle
 */
class InMemoryResponseDao : ResponseDao {

    private val items = MutableStateFlow<List<ResultEntity>>(emptyList())

    /**
     * Inserts a result entity into the in-memory store.
     * Replaces existing result if same ID exists.
     *
     * @param result The ResultEntity to insert
     */
    override suspend fun insertResult(result: ResultEntity) {
        items.value = listOf(result) + items.value.filterNot { it.id == result.id }
    }

    /**
     * Retrieves all results ordered by timestamp (newest first).
     *
     * @return Flow of ResultEntity list
     */
    override fun getAllResults(): Flow<List<ResultEntity>> {
        return items.map { list -> 
            list.sortedByDescending { it.timestamp } 
        }
    }

    /**
     * Deletes a result entity from the in-memory store.
     *
     * @param result The ResultEntity to delete
     */
    override suspend fun deleteResult(result: ResultEntity) {
        items.value = items.value.filterNot { 
            it.id == result.id && it.timestamp == result.timestamp 
        }
    }

    /**
     * Retrieves a single result by analysis type.
     *
     * @param analysisType The analysis type to search for
     * @return The first ResultEntity matching the analysis type, or null if not found
     */
    override suspend fun getResultByAnalysisType(analysisType: String): ResultEntity? {
        return items.value.firstOrNull { it.analysisType == analysisType }
    }
}

package com.example.agriculturalapp.data.provider

import com.example.agriculturalapp.data.local.AnalysisType

object StaticDataProvider {

    fun getPromptTemplate(analysisType: AnalysisType): String {
        return when (analysisType) {
            AnalysisType.IRRIGATION ->
                "As an agricultural expert, analyze the irrigation setup using the following farm data:\n%FARM_DATA%\nProvide practical recommendations."
            AnalysisType.PLANTING_ADVICE ->
                "As an agricultural expert, provide planting advice based on this farm data:\n%FARM_DATA%\nInclude timing, spacing, and crop-specific guidance."
            AnalysisType.PEST_CONTROL ->
                "As an agricultural expert, suggest pest control actions using this farm data:\n%FARM_DATA%\nPrioritize safe and effective methods."
            AnalysisType.SOIL_HEALTH ->
                "As an agricultural expert, assess soil health from this farm data:\n%FARM_DATA%\nRecommend improvement steps."
        }
    }
}

package com.example.agriculturalapp.domain.usecase


import com.example.agriculturalapp.data.static.StaticDataProvider
import com.example.agriculturalapp.domain.entity.AnalysisInput
import javax.inject.Inject

class GeneratePromptUseCase @Inject constructor() {

    operator fun invoke(input: AnalysisInput): String {
        val analysisType = input.analysisType
        val template = StaticDataProvider.getPromptTemplate(analysisType)

        // Format farm data from input
        val farmDataText = input.formData.entries.joinToString("\n") { (key, value) ->
            "- $key: $value"
        }

        return template.replace("%FARM_DATA%", farmDataText)
    }
}

